use regex::{Regex, RegexSet};
use std::{path::Path, sync::LazyLock};

static COMMENT: LazyLock<Regex> = LazyLock::new(|| {
    crate::literal_regex(
        r#"(?i)^\s*(?://|/\*+|\*+/?|#+|--+|<!--|%+|;+|'|!|\(\*|\{-|"""|'''|=begin|<#|@rem\b|rem\b)"#,
    )
});
static GENERATED_STEM: LazyLock<Regex> = LazyLock::new(|| crate::literal_regex(r"(?i)generat"));
static BANNERS: LazyLock<RegexSet> = LazyLock::new(|| {
    let patterns = [
        r"(?i)\bcode generated\b.{0,200}?\bdo not edit\b",
        r"(?i)\b(?:automatically |auto[- ]?)?generated (?:by|from|with)\b.{0,200}?\bdo not (?:edit|modify|change)\b",
        r"(?:^|[^\p{L}\p{N}_@])@generated\b",
        r"(?i)<auto-?generated\s*/?>",
        r"(?i)\b(?:automatically generated|auto[- ]?generated|autogenerated) by\b",
        r"(?i)\bgenerated by\s+\S.{0,80}?\bby running\b",
        r"(?i)\bthis (?:file|class|code|module) (?:is|was) (?:auto[- ]?)?generated\b",
        r"(?i)\bdo not (?:edit|modify)\b.{0,120}?\b(?:auto[- ]?generated|generated file|generated code)\b",
    ];
    match RegexSet::new(patterns) {
        Ok(set) => set,
        Err(error) => panic!("invalid static banner patterns: {error}"),
    }
});
static WEBPACK: LazyLock<Regex> =
    LazyLock::new(|| crate::literal_regex(r"\bfunction __webpack_require__\s*\("));

pub(crate) fn detect(path: &str, content: &str) -> bool {
    crate::textutil::is_generated_file(path) || has_banner(content) || minified(path, content)
}

fn has_banner(content: &str) -> bool {
    let mut units = 0;
    let end = content
        .char_indices()
        .find_map(|(index, ch)| {
            units += ch.len_utf16();
            (units > 8192).then_some(index)
        })
        .unwrap_or(content.len());
    let head = &content[..end];
    if !GENERATED_STEM.is_match(head) {
        return false;
    }

    let mut block_end = None;
    for line in head.lines().take(60) {
        if (block_end.is_some() || COMMENT.is_match(line)) && BANNERS.is_match(line) {
            return true;
        }
        if let Some(end) = block_end {
            if line.contains(end) {
                block_end = None;
            }
            continue;
        }
        for (open, close) in [
            ("/*", "*/"),
            ("<!--", "-->"),
            ("\"\"\"", "\"\"\""),
            ("'''", "'''"),
            ("=begin", "=end"),
            ("<#", "#>"),
        ] {
            if let Some((_, tail)) = line.split_once(open) {
                if !tail.contains(close) {
                    block_end = Some(close);
                }
                break;
            }
        }
    }
    false
}

fn minified(path: &str, content: &str) -> bool {
    let extension = Path::new(path).extension().and_then(|ext| ext.to_str());
    if content.len() < 4000
        || !extension.is_some_and(|ext| {
            ["js", "mjs", "cjs"]
                .iter()
                .any(|e| e.eq_ignore_ascii_case(ext))
        })
    {
        return false;
    }
    if WEBPACK.is_match(content) {
        return true;
    }
    let mut long = 0;
    let mut punctuation = 0;
    for line in content.split('\n') {
        let units = line.encode_utf16().count();
        if units >= 1000 {
            long += units;
            punctuation += line.bytes().filter(|b| b";{}(),".contains(b)).count();
        }
    }
    let units = content.encode_utf16().count();
    units >= 4000 && long * 2 >= units && punctuation * 100 >= long * 3
}
